-- Lote 03 do catálogo de talentos SRD: traduções revisadas.
-- Não altera engine_status: tradução não comprova integração funcional.
begin;
update public.srd_feats set nome_pt='Fintar Aprimorado', descricao_pt='Pré-requisitos: Inteligência 13, Especialização em Combate.\n\nBenefício: Você pode realizar um teste de Blefar para fintar em combate usando uma ação de movimento.\n\nNormal: Fintar em combate exige uma ação padrão.\n\nUm guerreiro pode escolher Fintar Aprimorado como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_improved_feint';
update public.srd_feats set nome_pt='Agarrar Aprimorado', descricao_pt='Pré-requisitos: Destreza 13, Ataque Desarmado Aprimorado.\n\nBenefício: Você não provoca um ataque de oportunidade quando realiza um ataque de toque para iniciar uma manobra de agarrar. Além disso, recebe +4 de bônus em todos os testes de agarrar, independentemente de ter iniciado a manobra.\n\nNormal: Sem este talento, você provoca um ataque de oportunidade quando realiza um ataque de toque para iniciar uma manobra de agarrar.\n\nEspecial: Um guerreiro pode escolher Agarrar Aprimorado como um de seus talentos adicionais de guerreiro. Um monge pode escolhê-lo como talento adicional no 1º nível, mesmo que não cumpra os pré-requisitos.' where id='srd35_feat_improved_grapple';
update public.srd_feats set nome_pt='Derrubar Aprimorado', descricao_pt='Pré-requisitos: Força 13, Ataque Poderoso.\n\nBenefício: Quando você tenta derrubar um oponente, o alvo não pode escolher evitar você. Além disso, recebe +4 de bônus no teste de Força para derrubar o oponente.\n\nNormal: Sem este talento, o alvo de uma tentativa de atropelar pode escolher evitar você ou bloqueá-lo.\n\nEspecial: Um guerreiro pode escolher Derrubar Aprimorado como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_improved_overrun';
update public.srd_feats set nome_pt='Tiro Preciso Aprimorado', descricao_pt='Pré-requisitos: Destreza 19, Tiro Certeiro, Tiro Preciso, bônus base de ataque +11.\n\nBenefício: Seus ataques à distância ignoram o bônus na Classe de Armadura concedido aos alvos por qualquer cobertura que não seja total e a chance de falha concedida por qualquer ocultação que não seja total. Cobertura total e ocultação total mantêm seus benefícios normais contra seus ataques à distância.\n\nAlém disso, quando você dispara ou arremessa armas à distância contra um oponente envolvido em uma manobra de agarrar, acerta automaticamente o oponente que escolheu como alvo.\n\nNormal: Consulte as regras normais sobre os efeitos de cobertura e ocultação. Sem este talento, um personagem que dispara ou arremessa uma arma à distância contra um alvo envolvido em uma manobra de agarrar deve determinar aleatoriamente qual combatente será atingido.\n\nEspecial: Um guerreiro pode escolher Tiro Preciso Aprimorado como um de seus talentos adicionais de guerreiro. Um ranger de 11º nível que tenha escolhido o estilo de combate com arco é considerado como possuidor deste talento, mesmo sem cumprir seus pré-requisitos, mas somente quando estiver usando armadura leve ou nenhuma armadura.' where id='srd35_feat_improved_precise_shot';
update public.srd_feats set nome_pt='Bater com Escudo Aprimorado', descricao_pt='Pré-requisito: Proficiência com Escudo.\n\nBenefício: Quando você realiza um ataque com escudo, ainda pode aplicar o bônus de escudo à sua Classe de Armadura.\n\nNormal: Sem este talento, um personagem que realiza um ataque com escudo perde o bônus de escudo na CA até seu próximo turno.\n\nEspecial: Um guerreiro pode escolher Bater com Escudo Aprimorado como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_improved_shield_bash';
update public.srd_feats set nome_pt='Despedaçar Aprimorado', descricao_pt='Pré-requisitos: Força 13, Ataque Poderoso.\n\nBenefício: Quando você ataca um objeto segurado ou carregado por um oponente, como uma arma ou escudo, não provoca um ataque de oportunidade. Além disso, recebe +4 de bônus em qualquer jogada de ataque realizada contra um objeto segurado ou carregado por outro personagem.\n\nNormal: Sem este talento, você provoca um ataque de oportunidade quando ataca um objeto segurado ou carregado por outro personagem.\n\nEspecial: Um guerreiro pode escolher Despedaçar Aprimorado como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_improved_sunder';
update public.srd_feats set nome_pt='Encontrão Aprimorado', descricao_pt='Pré-requisitos: Inteligência 13, Especialização em Combate.\n\nBenefício: Você não provoca um ataque de oportunidade quando tenta derrubar um oponente enquanto está desarmado. Além disso, recebe +4 de bônus no teste de Força para derrubar o oponente.\n\nSe você derrubar um oponente em combate corpo a corpo, recebe imediatamente um ataque corpo a corpo contra ele, como se não tivesse usado seu ataque para realizar a tentativa de derrubada.\n\nNormal: Sem este talento, você provoca um ataque de oportunidade quando tenta derrubar um oponente enquanto está desarmado.\n\nEspecial: Um monge de 6º nível pode escolher Encontrão Aprimorado como talento adicional, mesmo sem cumprir os pré-requisitos. Um guerreiro também pode escolhê-lo como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_improved_trip';
update public.srd_feats set nome_pt='Expulsão Aprimorada', descricao_pt='Pré-requisito: Capacidade de expulsar ou repreender criaturas.\n\nBenefício: Você expulsa ou repreende criaturas como se tivesse um nível a mais na classe que concede essa capacidade.' where id='srd35_feat_improved_turning';
update public.srd_feats set nome_pt='Combater com Duas Armas Aprimorado', descricao_pt='Pré-requisitos: Destreza 17, Combater com Duas Armas, bônus base de ataque +6.\n\nBenefício: Além do ataque adicional normal que você recebe com uma arma na mão inábil, recebe um segundo ataque com ela, embora com penalidade de –5.\n\nNormal: Sem este talento, você só pode realizar um ataque adicional com uma arma na mão inábil.\n\nEspecial: Um guerreiro pode escolher Combater com Duas Armas Aprimorado como um de seus talentos adicionais de guerreiro. Um ranger de 6º nível que tenha escolhido o estilo de combate com duas armas é considerado como possuidor deste talento, mesmo sem cumprir os pré-requisitos, mas somente quando estiver usando armadura leve ou nenhuma armadura.' where id='srd35_feat_improved_two_weapon_fighting';
update public.srd_feats set nome_pt='Ataque Desarmado Aprimorado', descricao_pt='Benefício: Você é considerado armado mesmo quando está desarmado; isto é, não provoca ataques de oportunidade de oponentes armados quando os ataca desarmado. Entretanto, você ainda pode realizar um ataque de oportunidade contra qualquer oponente que faça um ataque desarmado contra você.\n\nAlém disso, seus ataques desarmados podem causar dano letal ou não letal, à sua escolha.\n\nNormal: Sem este talento, você é considerado desarmado quando ataca com um golpe desarmado e só pode causar dano não letal com esse ataque.\n\nEspecial: Um monge recebe automaticamente Ataque Desarmado Aprimorado como talento adicional no 1º nível. Ela não precisa escolhê-lo. Um guerreiro pode escolhê-lo como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_improved_unarmed_strike';
update public.srd_feats set nome_pt='Investigador', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de Obter Informação e Procurar.' where id='srd35_feat_investigator';
update public.srd_feats set nome_pt='Vontade de Ferro', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de resistência de Vontade.' where id='srd35_feat_iron_will';
commit;